INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '5200d94b-cca2-4927-89bf-48c2c4f527fd', ct.id, $ctx$Lee voted Yea on LD 1955, significantly expanding child care affordability subsidies and educator stability funding (House 77-65, 3/5/2026), matching stance 2.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099161&chamber=House&serialnumber=634','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
