INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '5200d94b-cca2-4927-89bf-48c2c4f527fd', ct.id, $ctx$Lee voted Yea on LD 427, repealing mandatory parking space minimums in state/municipal building codes (House 82-65, 6/16/2025), a multimodal-friendly land-use reform matching stance 2.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280096272&chamber=H&serialnumber=534','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=427']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
