INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '5200d94b-cca2-4927-89bf-48c2c4f527fd', ct.id, $ctx$Lee voted Yea on LD 229, adding new income-tax brackets up to 8.2% above roughly $205,000 (House 76-71, 6/13/2025). Supporting this bracket increase on high earners matches stance 2.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095865&chamber=House&serialnumber=474','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
