INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '65ce1f05-e156-4f5a-9e21-4241cc958c19', ct.id, $ctx$Voted Nay on the June 18, 2025 Enactment of LD 1971 (opposing restrictions on local-federal immigration cooperation) and Nay on the motion to accept the Ought Not To Pass report on LD 1656 (a Nay-on-ONTP vote that kept alive a bill facilitating local compliance with federal immigration law) -- a consistent pro-cooperation position.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=House&serialnumber=574','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280098509&chamber=House&serialnumber=540','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1656']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
