INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'ec48f5a7-1efd-4942-8e13-65584102df0d', ct.id, $ctx$Voted Yea on the June 13, 2025 motion to accept the Ought Not To Pass report on LD 1134 -- a Yea-on-ONTP vote that killed a bill requiring athletes to compete based on biological sex, indicating support for allowing transgender athletes to compete on teams matching their gender identity without additional restriction.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=House&serialnumber=481','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
