INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'd7ad5924-0e8a-4d11-93e3-56e1db5dd019', ct.id, $ctx$Voted Yea on LD 1955, expanding child-care subsidies and early-educator stability grants; House vote 3/5/2026.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099161&chamber=H&serialnumber=634','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
