INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'd7ad5924-0e8a-4d11-93e3-56e1db5dd019', ct.id, $ctx$Voted Yea on LD 1870 (Climate Superfund Cost Recovery Program penalizing climate polluters); passed the House 75-72 and was signed into law 4/16/2026. He was absent for the companion LD 2037 RGGI-allowance vote, so LD 1870 alone anchors this row.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099027&chamber=H&serialnumber=708','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1870']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
