INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'd7ad5924-0e8a-4d11-93e3-56e1db5dd019', ct.id, $ctx$Voted Yea on LD 2077, a targeted first-time-buyer mortgage-rate grant program; passed House 4/6/2026.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101124&chamber=H&serialnumber=715','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2077']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
