INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'd7ad5924-0e8a-4d11-93e3-56e1db5dd019', ct.id, $ctx$Voted Yea on the enactment motion for LD 1948 (emergency MaineCare supplemental funding); received a 93-50 majority on 5/20/2025 but fell short of the two-thirds threshold.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099172&chamber=H&serialnumber=160','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1948']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='medicare/aid' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
