INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'bb7a224e-a0af-4bd8-a2a9-d70c35e1eefc', ct.id, $ctx$Voted Yea to accept the Ought Not to Pass report on LD 174 (restoring broad religious exemptions from immunization law), killing it; House vote 5/6/2025 (motion inverted).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095762&chamber=H&serialnumber=110','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=174']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='religious-freedom' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
