INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'bb7a224e-a0af-4bd8-a2a9-d70c35e1eefc', ct.id, $ctx$Voted Yea to accept the Ought Not to Pass report on LD 1134 (bio-sex sports/facilities restriction bill), killing it 73-72 on 6/13/2025; motion inverted, so a Yea preserves current practice allowing transgender athletes to compete.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=H&serialnumber=481','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
