INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '39fda5ab-f9fc-4e4c-a02a-1a86b55f4d32', ct.id, $ctx$Voted Yea on enactment of LD 2037 (2/26/2026, 71-66), updating Maine's Regional Greenhouse Gas Initiative allowances — an incremental, market-based emissions program rather than a ban or mandated fossil-fuel phase-out. Matches stance 3.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2037&SessionID=16','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280100902&chamber=H&serialnumber=627']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
