INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '39fda5ab-f9fc-4e4c-a02a-1a86b55f4d32', ct.id, $ctx$Voted Yea on enactment of LD 1765 (6/13/2025, 75-69), 'An Act to Ensure Affordability and Stability in Housing for Mobile Home Park Residents,' signed into law 6/18/2025. Targeted protection for a specific vulnerable homeowner class, rather than broad public housing or market deregulation, matches stance 3.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1765&SessionID=16','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280098765&chamber=House&serialnumber=469']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
