INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '14f6c68b-af34-495e-9179-9c767dd9f222', ct.id, $ctx$Boyer (Poland) voted Nay on LD 229, 'An Act to Bring Fairness in Income Taxes to Maine Families,' which added new tax brackets up to 8.2% on income above roughly $205,000 and was enacted 76-71 in the House on 6/13/2025. Opposing this bracket increase matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095865&chamber=House&serialnumber=474','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
