INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '5abdd7d2-32f2-455d-bfbb-95a75b0c7d3e', ct.id, $ctx$Rollins voted Yea on LD 2077, 'An Act to Reduce the Cost of Purchasing a Home by Providing Grants to Reduce Mortgage Rates,' which the House passed 78-66 on 4/2/2026. Supporting this targeted first-time-homebuyer mortgage-rate subsidy matches stance 3.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101124&chamber=House&serialnumber=715','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2077']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
