INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0316ee2f-fe0c-4122-a95a-2f43f55ce260', ct.id, $ctx$Sponsored LD 179 (bail code reform removing the Class E crime for violating release conditions), LD 268 (removing mandatory minimum sentences to restore judicial sentencing discretion), and LD 449 (authorizing conditional discharge for certain defendants) — all aimed at reducing the incarcerated population through bail, sentencing, and diversion reform rather than building detention capacity. Matches stance 2.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=179&SessionID=16','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=268&SessionID=16','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=449&SessionID=16']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='jail-capacity' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
