INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0316ee2f-fe0c-4122-a95a-2f43f55ce260', ct.id, $ctx$Voted Yea on final enactment of LD 1971 (6/18/2025, 75-73), which bars state and local law enforcement from using resources for civil immigration enforcement or complying with ICE hold requests except when authorized by a court order or criminal warrant, or in narrow public-safety exceptions. Matches stance 2 (comply only with court-ordered detainers).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971&SessionID=16','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=H&serialnumber=574']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
