INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0316ee2f-fe0c-4122-a95a-2f43f55ce260', ct.id, $ctx$Voted Yea on enactment of LD 229 (6/13/2025, 76-71), which adds three new, higher income-tax brackets (7.52%-8.2%) on income above roughly $205,000-$1,000,000 while raising the thresholds for existing lower brackets — a moderate tax increase on higher earners. Matches stance 2.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229&SessionID=16','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095865&chamber=House&serialnumber=474','https://legislature.maine.gov/legis/bills/getPDF.asp?paper=HP0152&item=1&snum=132']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
