INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'fe465340-16b2-43c4-8d0a-d748b201f3d5', ct.id, $ctx$Voted Nay on LD 1955 (House Roll Call #634, 3/5/2026), 'An Act to Increase Child Care Affordability and Early Childhood Educator Stability,' which passed 77-65 over his opposition. Opposing this subsidy/provider-support expansion reflects a preference for limiting new childcare subsidy programs.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099161&chamber=House&serialnumber=634']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
