INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'f7303b7d-0e06-4037-b9a4-9c7d12f37d6e', ct.id, $ctx$Voted Yea for OTP-as-amended of LD 1870 (Climate Superfund Cost Recovery Program, penalizing climate polluters) and Yea for enactment of LD 2037 (updating Maine's Regional Greenhouse Gas Initiative participation) -- both support market-based climate accountability and clean-energy investment.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1870','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099027&chamber=House&serialnumber=708','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2037']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
