INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'f7303b7d-0e06-4037-b9a4-9c7d12f37d6e', ct.id, $ctx$Voted Yea for OTP-as-amended of LD 2077, "An Act to Reduce the Cost of Purchasing a Home by Providing Grants to Reduce Mortgage Rates." As primary sponsor of LD 1781, he also won final House approval (6/23/2023) for a state-funded homeless substance-use-disorder housing and treatment service program for at least 100 Maine residents, publicly funding housing for a targeted vulnerable population.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2077','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101124&chamber=House&serialnumber=715','https://www.maine.gov/housedems/news/house-gives-final-approval-gattine-bill-establish-homeless-substance-use-disorder-service']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
