INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'f7303b7d-0e06-4037-b9a4-9c7d12f37d6e', ct.id, $ctx$Voted Yea on 6/18/2025 for enactment of LD 1971, which clarifies that state and local police may not proactively cooperate with federal immigration authorities absent a court order, and voted Yea on 6/17/2025 to accept the Ought-Not-to-Pass report killing LD 1656, a competing bill that would have facilitated compliance/cooperation with federal immigration law.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=House&serialnumber=574','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1656']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
