INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'f7303b7d-0e06-4037-b9a4-9c7d12f37d6e', ct.id, $ctx$Voted Yea for enactment of LD 229, "An Act to Bring Fairness in Income Taxes to Maine Families," which adjusts income tax brackets to reduce the burden on middle-income Mainers -- notable weight given Gattine chairs the House Appropriations and Financial Affairs Committee.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095865&chamber=House&serialnumber=474','https://www.maine.gov/housedems/news/gattine-named-house-chair-legislatures-appropriations-and-financial-affairs-committee']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
