INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'f7303b7d-0e06-4037-b9a4-9c7d12f37d6e', ct.id, $ctx$Voted Yea on 6/13/2025 to accept the Ought-Not-to-Pass report on LD 1134, "An Act to Prohibit Males from Participating in Female Sports or Using Female Facilities," killing the bio-sex-only restriction and preserving the existing policy of participation matching gender identity.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=House&serialnumber=481']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
