INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '34a3fabb-809d-4d11-866d-d270b4922f7e', ct.id, $ctx$Voted Yea on House Roll Call #574 (6/18/2025) for LD 1971, which became law (PL ch. 517) and bars state and local law enforcement from using resources for immigration enforcement, detaining people solely on ICE hold requests, or transferring people to ICE absent a court order or warrant. Supporting this law that refuses ICE detainers and restricts sharing of personal immigration-status information matches stance 1.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=H&serialnumber=574','https://legislature.maine.gov/legis/bills/getPDF.asp?paper=HP1315&item=3&snum=132']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
