INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '80747346-be87-4d1b-9bf6-9ee80356ba7f', ct.id, $ctx$Voted Nay on LD 2077 (House Roll Call #715, 4/2/2026), which provided grants to reduce mortgage rates for homebuyers; the bill passed 78-66 anyway. Opposing this targeted homebuyer-subsidy program reflects a preference for reduced government intervention in housing costs.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2077','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101124&chamber=House&serialnumber=715']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
