INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '80747346-be87-4d1b-9bf6-9ee80356ba7f', ct.id, $ctx$Voted Nay on LD 1971 (House Roll Call #574, 6/18/2025), which restricted state and local police cooperation with federal immigration authorities; the bill passed 74-73 over her opposition and became law without the Governor's signature. Opposing this restriction reflects support for continued local law-enforcement cooperation with federal immigration authorities.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=H&serialnumber=574']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
