INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '21f45688-4e19-42bb-b1c0-e17b5dba2d3a', ct.id, $ctx$Voted Yea on LD 427, which eliminated mandatory parking-space minimums in state and municipal building codes (House Roll Call #534, 6/16/2025; enacted as Public Law Ch. 374). Supporting removal of parking mandates aligns with stance 1 (reduce parking requirements citywide).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280096272&chamber=H&serialnumber=534','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=427']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
