INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '21f45688-4e19-42bb-b1c0-e17b5dba2d3a', ct.id, $ctx$Voted Yea to accept 'Ought Not to Pass' on LD 1134, which would have restricted school sports and facilities access to a student's biological sex (House Roll Call #481, 6/13/2025); her Yea vote helped kill the restrictive bill (73-72). Opposing a strict biological-sex mandate, without further evidence pinpointing her preferred alternative framework, aligns with stance 2.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=H&serialnumber=481','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '21f45688-4e19-42bb-b1c0-e17b5dba2d3a', ct.id, 2.0 FROM inform.compass_topics ct WHERE ct.topic_key='voting-rights' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '21f45688-4e19-42bb-b1c0-e17b5dba2d3a', ct.id, $ctx$Voted Yea to accept 'Ought Not to Pass' on LD 38, a photo-ID-for-voting bill; her Yea vote killed the ID mandate (72-69, 6/5/2025). Opposing a new photo-ID requirement, absent direct evidence of support for automatic registration or online voting specifically, aligns with stance 2 (expand access without new ID barriers).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095578&chamber=H&serialnumber=337','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=38']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='voting-rights' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
