INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '8e7b29b6-7396-4e29-bdd8-4fe19c646d8e', ct.id, $ctx$Drinkwater voted Nay (RC 337, 6/5/2025) against accepting the Ought Not to Pass report on LD 38, meaning he wanted the photo-ID-for-voting requirement to advance rather than die, directly matching support for a photo ID mandate.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=38','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095578&chamber=H&serialnumber=337']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='voting-rights' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
