INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '047962c6-216a-4ff6-b63e-04c900fb8af9', ct.id, $ctx$Friedmann voted Yea on LD 229, "An Act to Bring Fairness in Income Taxes to Maine Families by Adjusting the Tax Brackets and Tax Rates" (votes recorded 6/11 and 6/13/2025), supporting a bracket/rate adjustment intended to raise taxes on higher earners.$ctx$, ARRAY['https://legislature.maine.gov/house/MemberProfiles/RollCallByMember?sessionId=16&selectedMemberCode=FRIEGA','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229&SessionID=16']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
