INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '1f171f1f-14e4-47ef-b715-0d676e815568', ct.id, $ctx$Eaton voted Yea on LD 1955, "An Act to Increase Child Care Affordability and Early Childhood Educator Stability" (RC 634, 3/5/2026), supporting expanded child care subsidies and educator-stability funding.$ctx$, ARRAY['https://legislature.maine.gov/house/MemberProfiles/RollCallByMember?sessionId=16&selectedMemberCode=EATOHR','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955&SessionID=16']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
