INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '1f171f1f-14e4-47ef-b715-0d676e815568', ct.id, $ctx$Eaton voted Yea on enactment of LD 1870, the Climate Superfund Cost Recovery Program imposing penalties on climate polluters (RC 708, 3/31/2026), consistent with other votes that session supporting renewable-energy and emissions-accountability measures.$ctx$, ARRAY['https://legislature.maine.gov/house/MemberProfiles/RollCallByMember?sessionId=16&selectedMemberCode=EATOHR','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1870&SessionID=16']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
