INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '1f171f1f-14e4-47ef-b715-0d676e815568', ct.id, $ctx$Eaton voted Yea on LD 2232, "An Act to Increase County Jail Funding" (RC 706, 3/31/2026), supporting additional funding to expand county jail capacity and address overcrowding.$ctx$, ARRAY['https://legislature.maine.gov/house/MemberProfiles/RollCallByMember?sessionId=16&selectedMemberCode=EATOHR','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2232&SessionID=16']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='jail-capacity' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
