INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0199d6a7-271e-40b1-aad0-2cf262c7046b', ct.id, $ctx$Voted Yea on House Roll Call #803 (4/9/2026) to enact LD 2162, an emergency measure to regulate and restrict children's access to human-like AI chatbots and AI companions -- supporting a mandatory safety restriction on a high-risk AI use, matching stance 4's safety-testing/restriction approach for high-risk applications.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2162','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101203&chamber=House&serialnumber=803']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='ai-regulation' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '0199d6a7-271e-40b1-aad0-2cf262c7046b', ct.id, 2.0 FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0199d6a7-271e-40b1-aad0-2cf262c7046b', ct.id, $ctx$As a member of the Education and Cultural Affairs Committee, voted Yea on House Roll Call #634 (3/5/2026, LD 1955, to increase child care affordability and early-childhood-educator stability) and Yea on House Roll Call #666 (3/24/2026, LD 2114, expanding public preschool to 3-year-olds) -- supporting expanded subsidies, provider grants, and public preschool access, matching stance 2's significant subsidy/grant expansion rather than a fully universal free system or a market-only approach.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099161&chamber=House&serialnumber=634','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101155&chamber=House&serialnumber=666']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '0199d6a7-271e-40b1-aad0-2cf262c7046b', ct.id, 3.0 FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0199d6a7-271e-40b1-aad0-2cf262c7046b', ct.id, $ctx$Voted Yea on House Roll Call #627 (2/26/2026) to enact LD 2037, updating Maine's participation in the Regional Greenhouse Gas Initiative cap-and-trade carbon program -- supporting continuation of this incremental carbon-reduction mechanism, matching stance 3's gradual clean-energy investment approach rather than an emergency ban or market-only stance.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2037','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280100902&chamber=House&serialnumber=627']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '0199d6a7-271e-40b1-aad0-2cf262c7046b', ct.id, 2.0 FROM inform.compass_topics ct WHERE ct.topic_key='healthcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0199d6a7-271e-40b1-aad0-2cf262c7046b', ct.id, $ctx$Voted Yea on House Roll Call #738 (4/7/2026) to enact LD 2208, offsetting federal cuts to health insurance for Maine families and seniors -- supporting continued state action to keep coverage affordable through a mix of public assistance and private insurance, matching stance 2.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2208','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101545&chamber=House&serialnumber=738']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='healthcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
