INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'dc6a829a-5501-4f63-9d34-fa5210b80fc2', ct.id, $ctx$Voted Nay on the motion to accept the 'Ought Not to Pass' report on LD 1134 (House Roll Call #481, 6/13/2025), which would have restricted school sports and facility participation to biological sex; a Nay on this ONTP motion is a vote to keep the restrictive bill alive, and the motion to kill it failed narrowly 73-72.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=H&serialnumber=481']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
