INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '289e568d-a9e5-4e9d-9626-3b11891cd12b', ct.id, $ctx$Voted Nay on the motion to kill LD 1134 (6/13/2025, RC #481), keeping alive a bill to bar transgender athletes from female sports/facilities based on biological sex; also co-signed a January 2025 legislators' letter calling on the Maine Principals Association to "disallow individuals of differing biological sex from participating in competitions with those of the opposite sex."$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=House&serialnumber=481','https://mainehousegop.org/member_news_item/legislators-urge-education-department-to-comply-with-new-federal-guidelines/']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
