INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '54600569-46e8-4830-88c1-c86cabed4488', ct.id, 1.0 FROM inform.compass_topics ct WHERE ct.topic_key='abortion' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '54600569-46e8-4830-88c1-c86cabed4488', ct.id, $ctx$Per the Maine Right to Life 2025 House scorecard (Karen Montell's own recorded roll-call votes, 132nd Legislature), the representative voted AGAINST every MRTL-supported abortion restriction, including LD 253 (which would have barred the MaineCare program from covering abortion services) and LD 682 (narrowing legal abortion to a life-of-mother exception with criminal penalties), and voted to fund family-planning services (LD 143). Preserving public MaineCare funding and opposing restrictions at every stage matches chair 1 (legal, accessible, and publicly funded at all stages).$ctx$, ARRAY['https://mainerighttolife.org/wp-content/uploads/2025/07/2025-132nd-House-Roll-Call.pdf','https://legislature.maine.gov/legis/bills/display_ps.asp?LD=253&snum=132']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='abortion' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '54600569-46e8-4830-88c1-c86cabed4488', ct.id, 4.0 FROM inform.compass_topics ct WHERE ct.topic_key='ai-regulation' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '54600569-46e8-4830-88c1-c86cabed4488', ct.id, $ctx$Voted Yea on LD 2162 (4/9/2026, 104-43), which bars AI chatbots and 'social AI companions' with human-like features from being made accessible to minors, mandates age verification, and authorizes Attorney General civil penalties for violations. Supporting this mandatory compliance and use-restriction regime for a specific high-risk AI application matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2162&SessionID=16','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101203&chamber=H&serialnumber=803','https://legislature.maine.gov/legis/bills/getPDF.asp?paper=HP1451&item=1&snum=132']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='ai-regulation' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '54600569-46e8-4830-88c1-c86cabed4488', ct.id, 3.0 FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '54600569-46e8-4830-88c1-c86cabed4488', ct.id, $ctx$Voted Yea on enactment of LD 2037 (2/26/2026, 71-66), updating Maine's Regional Greenhouse Gas Initiative allowances — an incremental, market-based emissions program rather than a ban or mandated fossil-fuel phase-out. Matches stance 3.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2037&SessionID=16','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280100902&chamber=H&serialnumber=627']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '54600569-46e8-4830-88c1-c86cabed4488', ct.id, 3.0 FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '54600569-46e8-4830-88c1-c86cabed4488', ct.id, $ctx$Voted Yea on enactment of LD 1765 (6/13/2025, 75-69), 'An Act to Ensure Affordability and Stability in Housing for Mobile Home Park Residents,' signed into law 6/18/2025. Targeted protection for a specific vulnerable homeowner class, rather than broad public housing or market deregulation, matches stance 3.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1765&SessionID=16','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280098765&chamber=House&serialnumber=469']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
