INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '05b465cb-f538-4a17-bb47-a12e4409b62b', ct.id, $ctx$Voted Nay on enactment of LD 229, which adjusted Maine's income tax brackets and rates under a bill titled to 'bring fairness' to family taxation (House Roll Call #474, 6/13/2025; passed 76-71 over her objection). Opposing this bracket restructuring, absent further evidence of an affirmative push for rate cuts, is most consistent with stance 3 (keep the current tax system mostly as-is).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095865&chamber=H&serialnumber=474','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
