INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '05b465cb-f538-4a17-bb47-a12e4409b62b', ct.id, $ctx$Voted Nay on the motion to accept 'Ought Not to Pass' on LD 1134, which would have restricted school sports and facilities access to a student's biological sex (House Roll Call #481, 6/13/2025); her Nay means she wanted the restrictive bill to survive, though it ultimately died 73-72. This aligns with stance 4 (require competition on teams matching biological sex assigned at birth).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=H&serialnumber=481','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
