INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '05b465cb-f538-4a17-bb47-a12e4409b62b', ct.id, $ctx$Voted Nay on the motion to kill LD 38, a photo-ID-for-voting bill that also directed the Secretary of State to issue free ID cards to voters who lack one (House Roll Call #337, 6/5/2025; the 'Ought Not to Pass' motion prevailed 72-69, so her Nay means she wanted the ID bill to survive). Supporting a photo-ID mandate paired with guaranteed free IDs aligns with stance 3 (standardize voter ID requirements while ensuring free IDs are available).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095578&chamber=H&serialnumber=337','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=38']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='voting-rights' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
