INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '5d1feb93-3532-4e63-a175-5502fbcddae1', ct.id, $ctx$Voted Yea for enactment of LD 229, "An Act to Bring Fairness in Income Taxes to Maine Families," which adjusts income tax brackets to reduce the burden on middle-income Mainers. She separately introduced her own bill (presented 4/2/2025, reintroduced from a 2023 version) to exempt diapers and adult incontinence products from Maine's sales tax, framed as targeted relief for working families struggling with basic-necessity costs -- corroborating, though not the primary evidence for, her general working-family tax-relief orientation.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095865&chamber=House&serialnumber=474','https://www.maine.gov/housedems/news/murphy-presents-bill-lower-costs-maine-families-eliminating-sales-tax-diapers']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
