INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '496cc607-2296-4a7c-b2a0-0d56210805fd', ct.id, $ctx$On House Roll Call #803 (4/9/2026), Pomerleau voted Yea for enactment of LD 2162, the emergency child-safety AI chatbot regulation bill. Supporting this mandatory safety-testing regime matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101203&chamber=H&serialnumber=803','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2162']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='ai-regulation' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
