INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '496cc607-2296-4a7c-b2a0-0d56210805fd', ct.id, $ctx$On House Roll Call #634 (3/10/2026), Pomerleau voted Nay on LD 1955, the child-care-affordability/educator-stability bill. Opposing this subsidy expansion matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099161&chamber=House&serialnumber=634','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
