INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '496cc607-2296-4a7c-b2a0-0d56210805fd', ct.id, $ctx$Pomerleau voted Nay on both LD 1870 (House Roll Call #708, Climate Superfund polluter-pays program) and LD 2037 (House Roll Call #627, RGGI carbon-cap renewal). Opposing both climate/emissions programs matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099027&chamber=H&serialnumber=708','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280100902&chamber=H&serialnumber=627','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1870']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
