INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '7ebe7923-3a6a-464e-9646-4e688459f614', ct.id, $ctx$Voted Yea on House Roll Call #634 (3/5/2026, LD 1955, to increase child care affordability and early-childhood-educator stability) and Yea on House Roll Call #666 (3/24/2026, LD 2114, expanding public preschool to 3-year-olds) -- supporting expanded subsidies, provider grants, and public preschool access, matching stance 2's significant subsidy/grant expansion rather than a fully universal free system or a market-only approach.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099161&chamber=House&serialnumber=634','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101155&chamber=House&serialnumber=666']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
