INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '7ebe7923-3a6a-464e-9646-4e688459f614', ct.id, $ctx$Voted Yea on House Roll Call #627 (2/26/2026) to enact LD 2037, updating Maine's participation in the Regional Greenhouse Gas Initiative cap-and-trade carbon program -- supporting continuation of this incremental carbon-reduction mechanism, matching stance 3's gradual clean-energy investment approach rather than an emergency ban or market-only stance.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2037','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280100902&chamber=House&serialnumber=627']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
