INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'c1b625df-6943-49e8-a0a7-c603c4718ac1', ct.id, $ctx$Libby voted Nay on LD 1955, expanding child care affordability subsidies (House 77-65, 3/5/2026). Opposing this expansion matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099161&chamber=House&serialnumber=634','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
