INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '185b5de5-50a4-4a5b-9cef-f64f0ab1cb4c', ct.id, $ctx$Voted Yea (June 18, 2025) to enact LD 1971, which bars local police from civil immigration enforcement absent a court order or judicial warrant.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=House&serialnumber=574','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
