INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '2b061c70-8654-4725-98cd-373a13badf86', ct.id, $ctx$Co-signed the January 29, 2024 joint statement of Maine Republican legislators backing Texas's authority to defend its own border and criticizing federal immigration enforcement.$ctx$, ARRAY['https://mainehousegop.org/newsroom/maine-senate-house-republican-legislators-issue-joint-statement-supporting-texas-constitutional-right-to-defend-its-borders/']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
