INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6c9d5b66-c843-4170-ae7b-f516832b2312', ct.id, $ctx$Babin voted Yea on LD 2232, An Act to Increase County Jail Funding, on 3/31/2026 (roll call 706, motion to accept the majority Ought To Pass As Amended report, which prevailed 129-17), which was emergency-enacted as Public Law Ch. 721. This direct individual vote to expand jail-capacity funding matches 'building additional jail capacity to address overcrowding and facility deficiencies.'$ctx$, ARRAY['https://legislature.maine.gov/bills/display_ps.asp?snum=132&paper=HP1507&PID=1456','https://legislature.maine.gov/house/MemberProfiles/RollCallByMember?sessionId=16&selectedMemberCode=BABIMM']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='jail-capacity' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
