INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6c9d5b66-c843-4170-ae7b-f516832b2312', ct.id, $ctx$Babin was the lead signer of the Judiciary Committee minority 'Ought To Pass As Amended' report on LD 233, An Act to Prohibit Biological Males from Participating in School Athletic Programs and Activities Designated for Females (June 2025), advocating for the bill's passage; it ultimately died between houses. This direct committee-level advocacy for a biological-sex-based eligibility rule matches 'require transgender athletes to compete only on teams matching their biological sex assigned at birth.'$ctx$, ARRAY['https://legislature.maine.gov/bills/display_ps.asp?snum=132&paper=HP0156&PID=1456']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
