INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '307081dc-33cc-4bd2-9343-06fa90d29f03', ct.id, $ctx$Voted Nay on both LD 1870 (House Roll Call #708, 3/31/2026), a Climate Superfund program requiring major fossil fuel companies to pay for climate damages, and LD 2037 (House Roll Call #627), which tightened Regional Greenhouse Gas Initiative emissions allowances. Opposing both government-imposed climate accountability and cap-tightening measures indicates a preference for market forces over regulation, matching stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1870','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099027&chamber=House&serialnumber=708','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280100902&chamber=H&serialnumber=627']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
