INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '307081dc-33cc-4bd2-9343-06fa90d29f03', ct.id, $ctx$Voted Nay on House Roll Call #715 (4/2/2026) against LD 2077's program of state grants to reduce mortgage rates for homebuyers. Opposing a taxpayer-funded homebuyer subsidy indicates a preference for reduced government intervention in housing affordability, matching stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2077','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101124&chamber=House&serialnumber=715']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
