INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '307081dc-33cc-4bd2-9343-06fa90d29f03', ct.id, $ctx$Voted Nay on House Roll Call #574 (6/18/2025) against LD 1971, which became law (PL ch. 517) over his opposition and bars state/local law enforcement from using resources for immigration enforcement, detaining people solely on ICE hold requests, or transferring people to ICE absent a court order or warrant. Opposing this restriction indicates support for continued proactive cooperation with federal immigration authorities, matching stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=H&serialnumber=574','https://legislature.maine.gov/legis/bills/getPDF.asp?paper=HP1315&item=3&snum=132']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '307081dc-33cc-4bd2-9343-06fa90d29f03', ct.id, 4.0 FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '307081dc-33cc-4bd2-9343-06fa90d29f03', ct.id, $ctx$Voted Yea on House Roll Call #534 (6/16/2025) for LD 427, signed into law, which prohibits state and municipal building codes from imposing mandatory parking-space minimums -- breaking from the other two Republicans in this group, who voted Nay. Supporting a statewide reduction of local parking-requirement mandates to ease housing development matches stance 4's call to 'reduce parking requirements.'$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=427','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280096272&chamber=H&serialnumber=534']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
