INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '307081dc-33cc-4bd2-9343-06fa90d29f03', ct.id, $ctx$Voted Nay on House Roll Call #474 (6/13/2025) against LD 229, which added three new state income tax brackets (7.52%, 7.15%, 8.2%) on income above roughly $205,000 (single)/$410,000 (joint) while raising entry thresholds for existing lower brackets. Opposing new higher brackets on top earners in favor of the existing rate structure matches stance 3.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095865&chamber=House&serialnumber=474','https://legislature.maine.gov/legis/bills/getPDF.asp?paper=HP0152&item=1&snum=132']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '307081dc-33cc-4bd2-9343-06fa90d29f03', ct.id, 4.0 FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '307081dc-33cc-4bd2-9343-06fa90d29f03', ct.id, $ctx$Voted Nay on House Roll Call #481 (6/13/2025), opposing acceptance of the 'Ought Not to Pass' report on LD 1134 and thereby voting to keep alive a bill that would have barred transgender girls/women from participating in female school sports or using female facilities based on sex. This vote to advance a bill requiring competition by biological sex matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=H&serialnumber=481']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
