INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '96e540d3-cf64-412e-8a09-bf28f6689d15', ct.id, $ctx$On House Roll call #534 (6/16/2025), Walker voted Nay on LD 427, which repealed mandatory parking space minimums in state/municipal building codes. Opposing the repeal indicates a preference for maintaining current car-centric development standards, matching stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280096272&chamber=H&serialnumber=534','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=427']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
