INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '26fa2e76-137e-4ace-b40a-fc49105c2a05', ct.id, $ctx$On House Roll Call #715 (4/6/2026), Cimino voted Nay on LD 2077, the mortgage-rate-grant homebuyer bill. Opposing this subsidy program matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101124&chamber=House&serialnumber=715','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2077']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
