INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '26fa2e76-137e-4ace-b40a-fc49105c2a05', ct.id, $ctx$On House Roll Call #574 (6/18/2025), Cimino voted Nay on enactment of LD 1971, limiting local police cooperation with federal immigration authorities. She also voted Nay on House Roll Call #540 (6/17/2025) to accept the ONTP report on LD 1656, keeping the federal-compliance bill alive. Both votes match stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=H&serialnumber=574','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280098509&chamber=H&serialnumber=540','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
