INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '26fa2e76-137e-4ace-b40a-fc49105c2a05', ct.id, $ctx$On House Roll Call #534 (6/16/2025), Cimino voted Nay on LD 427, which repealed mandatory parking space minimums in state/municipal building codes. Opposing the repeal indicates a preference for maintaining current car-centric development standards, matching stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280096272&chamber=H&serialnumber=534','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=427']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
