INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0705d7cf-7e28-4543-9852-298bcafe4e66', ct.id, $ctx$Voted Yea on LD 2162, restricting children's access to human-like AI chatbot companions; passed House 104-43 on 4/9/2026.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101203&chamber=H&serialnumber=803','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2162']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='ai-regulation' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
