INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6e1fd819-cbf6-4f93-9917-220ad3294902', ct.id, $ctx$Voted Yea for OTP-as-amended of LD 1870 (Climate Superfund Cost Recovery Program, penalizing climate polluters to fund recovery costs) and Yea for enactment of LD 2037 (updating Maine's participation in the Regional Greenhouse Gas Initiative) -- both support market-based climate accountability and clean-energy investment mechanisms rather than an outright fossil-fuel ban or rejection of climate policy.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1870','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099027&chamber=House&serialnumber=708','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2037']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
