INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6e1fd819-cbf6-4f93-9917-220ad3294902', ct.id, $ctx$Voted Yea on the 5/20/2025 emergency Enactment vote for LD 1948, "An Act to Fund MaineCare," supporting a supplemental funding measure for the state's Medicaid program (the motion ultimately failed to reach the required two-thirds threshold).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1948','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099172&chamber=House&serialnumber=160']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='medicare/aid' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
