INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6e1fd819-cbf6-4f93-9917-220ad3294902', ct.id, $ctx$Voted Yea on 5/6/2025 to accept the Ought-Not-to-Pass report on LD 174, which would have restored religious exemptions to Maine's immunization requirements -- the vote to kill it favors public-health mandates over expanding religious exemptions.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=174','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095762&chamber=House&serialnumber=110']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='religious-freedom' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
