INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6e1fd819-cbf6-4f93-9917-220ad3294902', ct.id, $ctx$Voted Yea on 6/16/2025 on the Recede-and-Concur motion finalizing LD 427, which prohibits mandatory parking-space minimums in state and municipal building codes -- a deregulatory move explicitly aimed at reducing a cost barrier to denser development.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=427','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280096272&chamber=House&serialnumber=534']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
