INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6e1fd819-cbf6-4f93-9917-220ad3294902', ct.id, $ctx$Voted Yea on 5/20/2025 to accept the Ought-Not-to-Pass report on LD 220, which would have established the Hope and Inclusion Scholarship Program funding private-school and home-instruction students -- killing it keeps public dollars from being diverted to a new voucher-style program.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=220','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095877&chamber=House&serialnumber=145']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='school-vouchers' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
