INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6e1fd819-cbf6-4f93-9917-220ad3294902', ct.id, $ctx$Voted Yea for enactment of LD 229, "An Act to Bring Fairness in Income Taxes to Maine Families," which adjusts income tax brackets to reduce the burden on middle-income Mainers. He also co-authored a Jan 21, 2026 op-ed (with Rep. Cluchey) opposing automatic state conformity with recent federal tax changes, arguing they would send roughly $240 million in retroactive equipment-purchase breaks to large corporations, and endorsing LD 229 as a targeted alternative tax cut for working families.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095865&chamber=House&serialnumber=474','https://www.maine.gov/housedems/news/why-maine-should-reject-costly-federal-tax-changes-and-invest-working-families']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '6e1fd819-cbf6-4f93-9917-220ad3294902', ct.id, 1.0 FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6e1fd819-cbf6-4f93-9917-220ad3294902', ct.id, $ctx$Voted Yea on 6/13/2025 to accept the Ought-Not-to-Pass report on LD 1134, "An Act to Prohibit Males from Participating in Female Sports or Using Female Facilities," killing the bio-sex-only athletics/facilities restriction and preserving the existing policy of participation matching gender identity without added restrictions.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=House&serialnumber=481']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
