INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '9f8eebbe-19e1-4986-9f5f-563887a94462', ct.id, $ctx$Voted for LD 1955, "An Act to Increase Child Care Affordability and Early Childhood Educator Stability" (House Roll Call #634, 3/5/2026), which expands subsidies and provider support to make childcare more affordable and stabilize the childcare workforce.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099161&chamber=H&serialnumber=634']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
