INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'ee8f52bc-ad53-4abf-b136-3898ead3e41b', ct.id, $ctx$Voted Yea on House Roll Call #803 (4/9/2026) to enact LD 2162, an emergency measure to regulate and restrict children's access to human-like AI chatbots and AI companions -- supporting a mandatory safety restriction on a high-risk AI use, matching stance 4's safety-testing/restriction approach for high-risk applications.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2162','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101203&chamber=House&serialnumber=803']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='ai-regulation' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
