INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'ee8f52bc-ad53-4abf-b136-3898ead3e41b', ct.id, $ctx$Voted Yea on House Roll Call #481 (6/13/2025, LD 1134, to prohibit males from participating in female sports/facilities) and Yea on House Roll Call #492 (6/13/2025, LD 233, to prohibit biological males from female school athletics), both votes to accept 'Ought Not to Pass' and kill the restriction bills. Consistently voting to reject both bills evidences support for allowing transgender athletes to compete without added biological-sex-based restrictions.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=House&serialnumber=481','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095881&chamber=House&serialnumber=492']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
