INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '7e248174-dd02-4fc2-8995-943206641385', ct.id, $ctx$On House Roll Call #634 (3/10/2026), Wadsworth voted Nay on LD 1955, the child-care-affordability/educator-stability bill. Opposing this subsidy expansion matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099161&chamber=House&serialnumber=634','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
