INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '7e248174-dd02-4fc2-8995-943206641385', ct.id, $ctx$On House Roll Call #715 (4/6/2026), Wadsworth voted Nay on LD 2077, the mortgage-rate-grant homebuyer bill. Opposing this subsidy program matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101124&chamber=House&serialnumber=715','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2077']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '7e248174-dd02-4fc2-8995-943206641385', ct.id, 4.0 FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '7e248174-dd02-4fc2-8995-943206641385', ct.id, $ctx$On House Roll Call #574 (6/18/2025), Wadsworth voted Nay on enactment of LD 1971, limiting local police cooperation with federal immigration authorities. He also voted Nay on House Roll Call #540 (6/17/2025) to accept the Ought-Not-to-Pass report on LD 1656, a Nay-on-ONTP vote keeping the federal-compliance bill alive. Both votes point to supporting proactive local-federal immigration cooperation, matching stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=H&serialnumber=574','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280098509&chamber=H&serialnumber=540','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '7e248174-dd02-4fc2-8995-943206641385', ct.id, 4.0 FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '7e248174-dd02-4fc2-8995-943206641385', ct.id, $ctx$On House Roll Call #534 (6/16/2025), Wadsworth voted Nay on LD 427, which repealed mandatory parking space minimums in state/municipal building codes. Opposing the repeal indicates a preference for maintaining current car-centric development standards, matching stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280096272&chamber=H&serialnumber=534','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=427']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
