INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '1037ec72-4bfe-4d5c-87b8-4eb2fa7d998b', ct.id, $ctx$Milliken voted Yea to accept the committee's "ought not to pass" report on LD 1134, "An Act to Prohibit Males from Participating in Female Sports or Using Female Facilities" (RC 481, 6/13/2025), voting to kill the bill restricting transgender athletes, and cast matching votes against the related bills in the same cluster that session.$ctx$, ARRAY['https://legislature.maine.gov/house/MemberProfiles/RollCallByMember?sessionId=16&selectedMemberCode=MILLNA','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134&SessionID=16']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
