INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0cf86dbe-b7be-4cf1-977b-97a98fc60fa9', ct.id, $ctx$Voted Yea on House Roll Call #715 (4/2/2026) for LD 2077, which would have provided state grants to reduce mortgage rates for homebuyers (passed the House but died in the Senate). Supporting a targeted first-time-buyer mortgage subsidy program matches stance 3.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2077','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101124&chamber=House&serialnumber=715']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
