INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'a793b036-460a-4752-961f-53d460f8130a', ct.id, $ctx$Voted Nay on enactment of LD 1971, which restricts state and local law enforcement's cooperation with federal immigration authorities except in narrowly defined circumstances (House Roll Call #574, 6/18/2025; became law without the Governor's signature). He also voted Nay on the motion to accept 'Ought Not to Pass' on LD 1656, which would have required state/local compliance with federal immigration law -- his Nay means he wanted that compliance bill to survive (House Roll Call #540, 6/17/2025). Both votes favor law enforcement cooperating with ICE, aligning with stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=H&serialnumber=574','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280098509&chamber=H&serialnumber=540']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT 'a793b036-460a-4752-961f-53d460f8130a', ct.id, 4.0 FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'a793b036-460a-4752-961f-53d460f8130a', ct.id, $ctx$Voted Nay on LD 427, which prohibited mandatory parking-space minimums in state and municipal building codes (House Roll Call #534, 6/16/2025; enacted as Public Law Ch. 374 over his objection). Opposing removal of parking mandates aligns with stance 4 (transportation investment should serve the majority who drive).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280096272&chamber=H&serialnumber=534','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=427']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT 'a793b036-460a-4752-961f-53d460f8130a', ct.id, 3.0 FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'a793b036-460a-4752-961f-53d460f8130a', ct.id, $ctx$Voted Nay on enactment of LD 229, which adjusted Maine's income tax brackets and rates under a bill titled to 'bring fairness' to family taxation (House Roll Call #474, 6/13/2025; passed 76-71 over his objection). Opposing this bracket restructuring, absent further evidence of an affirmative push for rate cuts, is most consistent with stance 3 (keep the current tax system mostly as-is).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095865&chamber=H&serialnumber=474','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
