INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'a793b036-460a-4752-961f-53d460f8130a', ct.id, $ctx$Voted Nay on the motion to accept 'Ought Not to Pass' on LD 1134, which would have restricted school sports and facilities access to a student's biological sex (House Roll Call #481, 6/13/2025); his Nay means he wanted the restrictive bill to survive, though it ultimately died 73-72. This aligns with stance 4 (require competition on teams matching biological sex assigned at birth).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=H&serialnumber=481','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT 'a793b036-460a-4752-961f-53d460f8130a', ct.id, 3.0 FROM inform.compass_topics ct WHERE ct.topic_key='voting-rights' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'a793b036-460a-4752-961f-53d460f8130a', ct.id, $ctx$Voted Nay on the motion to kill LD 38, a photo-ID-for-voting bill that also directed the Secretary of State to issue free ID cards to voters who lack one (House Roll Call #337, 6/5/2025; the 'Ought Not to Pass' motion prevailed 72-69, so his Nay means he wanted the ID bill to survive). Supporting a photo-ID mandate paired with guaranteed free IDs aligns with stance 3 (standardize voter ID requirements while ensuring free IDs are available).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095578&chamber=H&serialnumber=337','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=38']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='voting-rights' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
