INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '233ca29f-b25c-4191-8cf4-3f529fb933e9', ct.id, $ctx$Chapman voted Nay on LD 2077, providing mortgage-rate grants to reduce home-buying costs (House 78-66, 4/2/2026). Opposing this subsidy matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101124&chamber=House&serialnumber=715','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2077']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
