INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '233ca29f-b25c-4191-8cf4-3f529fb933e9', ct.id, $ctx$Chapman voted Nay on LD 1971, barring local police from complying with civil immigration detainers absent a warrant (House 75-73, 6/18/2025), and Nay on the ONTP motion for LD 1656, wanting to keep alive a bill compelling local compliance with federal immigration law (House 77-71, 6/17/2025). Both match stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=H&serialnumber=574','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280098509&chamber=H&serialnumber=540']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
