INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'a37ec3f9-faa6-4c06-8856-92fa618a28ad', ct.id, $ctx$Henderson voted Nay on passage of LD 2077 (An Act to Reduce the Cost of Purchasing a Home by Providing Grants to Reduce Mortgage Rates), Roll Call 715 on 4/2/2026, opposing the mortgage-rate-assistance grant program (which nonetheless passed the House before dying in the Senate at adjournment).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2077','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280101124&chamber=H&serialnumber=715']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
