INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'a37ec3f9-faa6-4c06-8856-92fa618a28ad', ct.id, $ctx$Henderson voted Yea on the emergency enactment of LD 1948 (Fund MaineCare), Roll Call 160 on 5/20/2025, joining Bunker in supporting supplemental emergency MaineCare funding; the measure failed to reach the required two-thirds threshold.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1948','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280099172&chamber=H&serialnumber=160']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='medicare/aid' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
