INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'a37ec3f9-faa6-4c06-8856-92fa618a28ad', ct.id, $ctx$Henderson voted Nay on the motion to accept the Ought Not to Pass report on LD 174 (restore religious exemptions to immunization requirements), Roll Call 110 on 5/6/2025 -- opposing the majority and supporting restoration of the religious exemption.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=174','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280095762&chamber=H&serialnumber=110']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='religious-freedom' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
