INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'a37ec3f9-faa6-4c06-8856-92fa618a28ad', ct.id, $ctx$Henderson voted Nay on the House's motion to recede and concur in passing LD 427 (An Act to Prohibit Mandatory Parking Space Minimums in State and Municipal Building Codes), Roll Call 534 on 6/16/2025 -- opposing repeal of mandatory parking minimums (the bill passed anyway, 82-65, and was signed into law).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=427','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280096272&chamber=H&serialnumber=534']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
