INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'a37ec3f9-faa6-4c06-8856-92fa618a28ad', ct.id, $ctx$Henderson voted Nay on the motion to accept the Ought Not to Pass report on LD 220 (Hope and Inclusion Scholarship Program for private-school and home-instruction students), Roll Call 145 on 5/20/2025 -- opposing the majority and supporting the new voucher-style scholarship program. Henderson serves on the Judiciary Committee.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=220','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280095877&chamber=H&serialnumber=145']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='school-vouchers' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
