INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'e8cbe890-b3ac-44b9-baf3-d4d988b7c1cc', ct.id, $ctx$Hall voted Nay on the motion to accept the Ought to Pass as Amended report on LD 1870 (An Act to Establish a Climate Superfund Cost Recovery Program to Impose Penalties on Climate Polluters), Roll Call 708 on 3/31/2026 -- opposing this climate-accountability program (it nonetheless finally passed and was signed into law 4/16/2026).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1870','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280099027&chamber=H&serialnumber=708']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
