INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'e8cbe890-b3ac-44b9-baf3-d4d988b7c1cc', ct.id, $ctx$Hall voted Nay on the motion to accept the Ought Not to Pass report on LD 174 (An Act to Restore Religious Exemptions to Immunization Requirements), Roll Call 110 on 5/6/2025 -- opposing the majority's move to kill the bill and thereby supporting restoring a religious exemption to the state's immunization law.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=174','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280095762&chamber=H&serialnumber=110']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='religious-freedom' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
