INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'e8cbe890-b3ac-44b9-baf3-d4d988b7c1cc', ct.id, $ctx$Hall voted Nay on final enactment of LD 229 (adding three new state income-tax brackets reaching 8.2% on income above roughly $205,000), Roll Call 474 on 6/13/2025, opposing the tax increase on high earners (the bill passed anyway).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280095865&chamber=H&serialnumber=474']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
