INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'e8cbe890-b3ac-44b9-baf3-d4d988b7c1cc', ct.id, $ctx$Hall voted Nay on the motion to accept the Report B Ought Not to Pass on LD 1134 (An Act to Prohibit Males from Participating in Female Sports or Using Female Facilities), Roll Call 481 on 6/13/2025 -- opposing the move to kill the bill and thereby supporting a requirement that athletes compete based on biological sex (the bill nonetheless died, 73-72).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280097524&chamber=H&serialnumber=481']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
