INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'b43d9033-090f-4fea-9000-7f7360dbd0e6', ct.id, $ctx$Co-signed the January 29, 2024 joint statement by Maine House and Senate Republicans supporting Texas's constitutional right to defend its border and criticizing the Biden administration's border enforcement record.$ctx$, ARRAY['https://mainehousegop.org/newsroom/maine-senate-house-republican-legislators-issue-joint-statement-supporting-texas-constitutional-right-to-defend-its-borders/']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
