INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '775d8ed7-0f01-43e0-b7c3-cd7b7f80f9c2', ct.id, $ctx$Olsen voted Nay on LD 1955, 'An Act to Increase Child Care Affordability and Early Childhood Educator Stability,' which the House passed 77-65 on 3/5/2026. Opposing this subsidy expansion matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099161&chamber=House&serialnumber=634','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
