INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '775d8ed7-0f01-43e0-b7c3-cd7b7f80f9c2', ct.id, $ctx$Olsen voted Nay on LD 1870, 'An Act to Establish a Climate Superfund Cost Recovery Program to Impose Penalties on Climate Polluters,' which the House passed 75-72 on 3/31/2026 and the Governor signed 4/16/2026. Opposing this polluter cost-recovery program matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099027&chamber=House&serialnumber=708','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1870']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
