INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '775d8ed7-0f01-43e0-b7c3-cd7b7f80f9c2', ct.id, $ctx$Olsen voted Nay on LD 2077, 'An Act to Reduce the Cost of Purchasing a Home by Providing Grants to Reduce Mortgage Rates,' which the House passed 78-66 on 4/2/2026. Opposing this targeted homebuyer subsidy matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101124&chamber=House&serialnumber=715','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2077']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
