INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '775d8ed7-0f01-43e0-b7c3-cd7b7f80f9c2', ct.id, $ctx$Olsen voted Nay on LD 427, which repealed mandatory parking space minimums in state and municipal building codes (House 82-65, 6/16/2025; signed 6/20/2025). Opposing repeal of parking mandates matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280096272&chamber=H&serialnumber=534','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=427']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
