INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '775d8ed7-0f01-43e0-b7c3-cd7b7f80f9c2', ct.id, $ctx$Olsen voted Nay on LD 229, 'An Act to Bring Fairness in Income Taxes to Maine Families,' which added new tax brackets up to 8.2% on income above roughly $205,000 and was enacted 76-71 in the House on 6/13/2025. Opposing this bracket increase on high earners matches stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095865&chamber=House&serialnumber=474','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
