INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6ca03396-08d7-43ff-a101-f5a1aec11e3e', ct.id, $ctx$White voted Yea on LD 2162, "An Act to Regulate and Prevent Children's Access to Artificial Intelligence Chatbots with Human-like Features and Social Artificial Intelligence Companions" (RC 803, 4/9/2026, passed 104-43 as an emergency measure), supporting a government-mandated restriction on a specific high-risk AI use.$ctx$, ARRAY['https://legislature.maine.gov/house/MemberProfiles/RollCallByMember?sessionId=16&selectedMemberCode=WHITRP','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2162&SessionID=16']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='ai-regulation' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
