INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6ca03396-08d7-43ff-a101-f5a1aec11e3e', ct.id, $ctx$White voted Nay on LD 1955, "An Act to Increase Child Care Affordability and Early Childhood Educator Stability" (RC 634, 3/5/2026), opposing an expansion of child care subsidies and educator-stability funding sponsored by Senate President Daughtry.$ctx$, ARRAY['https://legislature.maine.gov/house/MemberProfiles/RollCallByMember?sessionId=16&selectedMemberCode=WHITRP','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955&SessionID=16']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
