INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6ca03396-08d7-43ff-a101-f5a1aec11e3e', ct.id, $ctx$White voted Yea on LD 2232, "An Act to Increase County Jail Funding" (RC 706, 3/31/2026, enacted as an emergency measure, Chapter 721), supporting additional funding to expand county jail capacity and address overcrowding.$ctx$, ARRAY['https://legislature.maine.gov/house/MemberProfiles/RollCallByMember?sessionId=16&selectedMemberCode=WHITRP','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2232&SessionID=16']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='jail-capacity' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
