INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6ca03396-08d7-43ff-a101-f5a1aec11e3e', ct.id, $ctx$White voted Nay on the motion to accept the Judiciary Committee's "ought not to pass" report on LD 1134, "An Act to Prohibit Males from Participating in Female Sports or Using Female Facilities" (RC 481, House vote 6/13/2025), meaning he voted against killing the bill and to keep it alive. This is consistent with requiring transgender athletes to compete on teams matching their sex assigned at birth.$ctx$, ARRAY['https://legislature.maine.gov/house/MemberProfiles/RollCallByMember?sessionId=16&selectedMemberCode=WHITRP','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134&SessionID=16']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
