INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '8b288fec-b935-40b3-a7b1-ecb65d184b51', ct.id, $ctx$Voted Yea on enactment of LD 2037 (2/26/2026, 71-66), updating Maine's Regional Greenhouse Gas Initiative allowances — an incremental, market-based emissions program rather than a ban or mandated fossil-fuel phase-out. Matches stance 3.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2037&SessionID=16','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280100902&chamber=H&serialnumber=627']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '8b288fec-b935-40b3-a7b1-ecb65d184b51', ct.id, 3.0 FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '8b288fec-b935-40b3-a7b1-ecb65d184b51', ct.id, $ctx$Voted Yea on enactment of LD 2231 (4/8/2026, 78-67), 'An Act to Support Owners of Manufactured Housing, Mobile Homes and Tiny Homes,' signed into law 4/13/2026. This targeted support for a specific class of affordable homeowners, rather than broad public housing or market deregulation, matches stance 3.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2231&SessionID=16','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101880&chamber=House&serialnumber=757']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
