INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '8d45a199-5054-417f-b9a9-3874e113c5f4', ct.id, $ctx$Voted Yea on LD 1971 (An Act to Protect Workers in This State by Clarifying the Relationship of State and Local Law Enforcement Agencies with Federal Immigration Authorities), which bars local police from federal civil immigration enforcement while preserving cooperation on serious crimes like trafficking; passed House 74-73 on 6/18/2025 and became law 1/11/2026. Also voted Yea to accept the Ought Not to Pass report on LD 1656, killing a bill that would have required local compliance with federal immigration enforcement requests.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=H&serialnumber=574','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280098509&chamber=H&serialnumber=540']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
