INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '8d45a199-5054-417f-b9a9-3874e113c5f4', ct.id, $ctx$Voted Yea to accept the committee's Ought Not to Pass report on LD 1134 (An Act to Prohibit Males from Participating in Female Sports or Using Female Facilities), killing the bio-sex restriction bill 73-72 on 6/13/2025; the motion is inverted, so a Yea preserves the status quo allowing transgender athletes to continue competing.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=H&serialnumber=481','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
