INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '9664affa-96b6-461f-976e-6cdf077cbf11', ct.id, $ctx$Voted Yea on LD 1870, "An Act to Establish a Climate Superfund Cost Recovery Program to Impose Penalties on Climate Polluters" (prevailed 75-72), and voted Yea on the related LD 2037 RGGI-allowance update (enacted 71-66, 2/26/2026), one day after taking office.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099027&chamber=House&serialnumber=708','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280100902&chamber=House&serialnumber=627','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1870']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
