INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '60bf7e1e-583d-4838-a455-e39765db03e2', ct.id, $ctx$Voted Nay on LD 1955, which expanded child-care subsidies and early-childhood educator stability funding (House Roll Call #634, 3/5/2026; passed 77-65 over her objection). Opposing expanded childcare subsidies aligns with stance 4 (reduce regulations, with limited subsidies reserved for the lowest-income families).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099161&chamber=H&serialnumber=634','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
