INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '60bf7e1e-583d-4838-a455-e39765db03e2', ct.id, $ctx$Voted Nay on LD 2037, which renewed Maine's participation in the Regional Greenhouse Gas Initiative and tightened its carbon emissions caps annually through 2037 (House Roll Call #627, 2/26/2026; enacted as Public Law Ch. 550 over her objection). Opposing continuation of this cap-and-trade emissions program aligns with stance 4 (let market forces drive any transition to cleaner energy).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280100902&chamber=H&serialnumber=627','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2037']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
