INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '60bf7e1e-583d-4838-a455-e39765db03e2', ct.id, $ctx$Voted Nay on enactment of LD 1971, which restricts state and local law enforcement's cooperation with federal immigration authorities except in narrowly defined circumstances (House Roll Call #574, 6/18/2025; became law without the Governor's signature). She also voted Nay on the motion to accept 'Ought Not to Pass' on LD 1656, which would have required state/local compliance with federal immigration law -- her Nay means she wanted that compliance bill to survive (House Roll Call #540, 6/17/2025). Both votes favor law enforcement cooperating with ICE, aligning with stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280099282&chamber=H&serialnumber=574','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280098509&chamber=H&serialnumber=540']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '60bf7e1e-583d-4838-a455-e39765db03e2', ct.id, 4.0 FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '60bf7e1e-583d-4838-a455-e39765db03e2', ct.id, $ctx$Voted Nay on LD 427, which prohibited mandatory parking-space minimums in state and municipal building codes (House Roll Call #534, 6/16/2025; enacted as Public Law Ch. 374 over her objection). Opposing removal of parking mandates aligns with stance 4 (transportation investment should serve the majority who drive).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280096272&chamber=H&serialnumber=534','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=427']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '60bf7e1e-583d-4838-a455-e39765db03e2', ct.id, 4.0 FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '60bf7e1e-583d-4838-a455-e39765db03e2', ct.id, $ctx$Voted Nay on enactment of LD 229, which adjusted Maine's income tax brackets and rates under a bill titled to 'bring fairness' to family taxation (House Roll Call #474, 6/13/2025; passed 76-71 over her objection). As Ranking Member of the Taxation Committee, she also delivered a November 24, 2023 Weekly Republican Radio Address explicitly calling for continued tax cuts so residents could keep more of their income. This explicit tax-cut framing, combined with her vote against the bracket-restructuring bill, aligns with stance 4 (cut taxes for everyone and scale back public services to match).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095865&chamber=H&serialnumber=474','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229','https://mainehousegop.org/member_news_item/personal-income-increased-everywhere-but-maine/']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) SELECT '60bf7e1e-583d-4838-a455-e39765db03e2', ct.id, 4.0 FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '60bf7e1e-583d-4838-a455-e39765db03e2', ct.id, $ctx$Voted Nay on the motion to accept 'Ought Not to Pass' on LD 1134, which would have restricted school sports and facilities access to a student's biological sex (House Roll Call #481, 6/13/2025); her Nay means she wanted the restrictive bill to survive, though it ultimately died 73-72. This aligns with stance 4 (require competition on teams matching biological sex assigned at birth).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=H&serialnumber=481','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
