INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'a5c70691-3834-48f8-aeca-79b95c131884', ct.id, $ctx$Bishop voted Nay on enactment of LD 1870, the Climate Superfund Cost Recovery Program that imposes penalties on climate polluters (RC 708, 3/31/2026), consistent with a broader pattern of votes that session against renewable-mandate and emissions-liability bills (RGGI update, equitable energy policy, community solar).$ctx$, ARRAY['https://legislature.maine.gov/house/MemberProfiles/RollCallByMember?sessionId=16&selectedMemberCode=BISHSM','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1870&SessionID=16']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
