INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'b08821e4-7a92-498c-97f2-13138777e8ae', ct.id, $ctx$Schmersal-Burgess voted Nay on the emergency enactment of LD 2162 (regulating children's access to AI chatbots with human-like features and social AI companions), Roll Call 803 on 4/9/2026 -- opposing this AI child-safety regulation, which nonetheless passed the House 104-43.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2162','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280101203&chamber=H&serialnumber=803']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='ai-regulation' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
