INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'b08821e4-7a92-498c-97f2-13138777e8ae', ct.id, $ctx$Schmersal-Burgess voted Nay on passage of LD 1955 (An Act to Increase Child Care Affordability and Early Childhood Educator Stability), Roll Call 634 on 3/5/2026, opposing the targeted childcare-subsidy and provider-stability bill (which nonetheless passed the House before dying in the Senate at adjournment).$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1955','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280099161&chamber=H&serialnumber=634']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
