INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'b08821e4-7a92-498c-97f2-13138777e8ae', ct.id, $ctx$Schmersal-Burgess voted Nay on final enactment of LD 1971 (limiting local police cooperation with federal immigration enforcement absent a court order), Roll Call 574 on 6/18/2025 (the bill passed anyway, 74-73), and voted Nay on the motion to accept the Ought Not to Pass report on LD 1656 (mandating compliance with federal immigration authorities), Roll Call 540 on 6/17/2025 -- opposing restrictions on local-federal immigration cooperation and supporting a mandate to comply with ICE.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1971','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280099282&chamber=H&serialnumber=574','http://www.mainelegislature.org/LawMakerWeb/rollcall.asp?ID=280098509&chamber=H&serialnumber=540']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
