INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'b13ec962-0772-4fdd-8399-59c3bc7fa19a', ct.id, $ctx$Voted Nay on House Roll Call #627 (2/26/2026) against enacting LD 2037, which updated Maine's Regional Greenhouse Gas Initiative carbon-allowance program -- opposing continuation of the state's cap-and-trade climate program, matching stance 4's preference for market-driven rather than government-directed energy transition.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2037','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280100902&chamber=House&serialnumber=627']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='climate-change' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
