INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'b13ec962-0772-4fdd-8399-59c3bc7fa19a', ct.id, $ctx$Voted Nay on House Roll Call #738 (4/7/2026) against enacting LD 2208, which offsets federal cuts to health insurance for Maine families and seniors -- opposing expanded state action to backstop coverage affordability, matching stance 4's limited-government approach that leaves coverage mainly to employers and private insurance.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2208','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101545&chamber=House&serialnumber=738']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='healthcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
