INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'b13ec962-0772-4fdd-8399-59c3bc7fa19a', ct.id, $ctx$Voted Nay on House Roll Call #540 (6/17/2025), opposing the majority's 'Ought Not to Pass' recommendation and thereby supporting LD 1656, a bill to facilitate state and local government compliance with federal immigration enforcement -- matching stance 4's support for honoring ICE requests and cooperating with federal immigration agencies.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1656','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280098509&chamber=House&serialnumber=540']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='local-immigration' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
