INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'b13ec962-0772-4fdd-8399-59c3bc7fa19a', ct.id, $ctx$Voted Nay on House Roll Call #529 (6/16/2025), opposing the 'Ought Not to Pass' motion and thereby supporting LD 1853, which would create a tax-credit program helping parents pay private/nonpublic-school tuition -- matching stance 4's support for expanding voucher-style eligibility for private-school costs.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1853','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280098955&chamber=House&serialnumber=529']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='school-vouchers' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
