INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'b13ec962-0772-4fdd-8399-59c3bc7fa19a', ct.id, $ctx$Voted Nay on House Roll Call #417 (6/10/2025), opposing the majority's 'Ought Not to Pass' recommendation and thereby supporting LD 856, 'An Act to Phase Out the Income Tax' -- matching stance 5's drastic-tax-cut position. His 2026 Ballotpedia Candidate Connection survey also names restoring the 2% municipal property-tax cap as his district's most significant issue.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=856','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097133&chamber=House&serialnumber=417','https://ballotpedia.org/Thomas_Lavigne']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
