INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0bbbb18d-1f67-4bd1-89d6-505a175d063c', ct.id, $ctx$Was absent for the LD 1955 childcare-affordability vote, but voted Yea on House Roll Call #666 (3/24/2026) to enact LD 2114, expanding public preschool programs to 3-year-olds -- supporting expanded public early-childhood access, matching stance 2's subsidy/grant-expansion approach.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2114','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101155&chamber=House&serialnumber=666']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='childcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
