INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0bbbb18d-1f67-4bd1-89d6-505a175d063c', ct.id, $ctx$Voted Yea on House Roll Call #738 (4/7/2026) to enact LD 2208, offsetting federal cuts to health insurance for Maine families and seniors -- supporting continued state action to keep coverage affordable through a mix of public assistance and private insurance, matching stance 2.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2208','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101545&chamber=House&serialnumber=738']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='healthcare' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
