INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0bbbb18d-1f67-4bd1-89d6-505a175d063c', ct.id, $ctx$Voted Yea on House Roll Call #699 (3/30/2026) to enact LD 2116, making permanent the state's Affordable Housing Income Tax Credit -- a targeted subsidy for affordable-housing projects, matching stance 3's 'subsidies for affordable projects' approach rather than direct public housing construction or a hands-off market approach.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2116','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280101160&chamber=House&serialnumber=699']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='housing' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
