INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '0bbbb18d-1f67-4bd1-89d6-505a175d063c', ct.id, $ctx$Voted Yea on House Roll Call #730 (4/2/2026) to enact LD 2058, requiring municipal and county jails to remain available at all times for detention of persons arrested on criminal charges -- supporting a mandate to maintain/expand jail availability rather than redirecting funds to alternatives, matching stance 4.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=2058','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280100951&chamber=House&serialnumber=730']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='jail-capacity' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
