INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6793f0eb-ddaa-4c72-ac99-70876295279a', ct.id, $ctx$Voted Yea on LD 427 (6/16/2025, House Roll Call #534), which repealed mandatory parking-space minimums in state and municipal building codes, directly matching the scale's "reduce parking requirements" chair for streamlined, higher-density development.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=427','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280096272&chamber=House&serialnumber=534']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='residential-zoning' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
