INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6793f0eb-ddaa-4c72-ac99-70876295279a', ct.id, $ctx$Voted Yea on the motion to kill LD 220 (5/20/2025, RC #145), the Hope and Inclusion Scholarship program that would have funded students at private schools and home instruction -- opposing the targeted voucher program favors prioritizing public school funding.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=220','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095877&chamber=House&serialnumber=145']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='school-vouchers' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
