INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6793f0eb-ddaa-4c72-ac99-70876295279a', ct.id, $ctx$Voted Yea on LD 229 (6/13/2025, RC #474), which added three new income tax brackets up to 8.2% on income above roughly $205,000 -- a moderate, targeted tax increase on high earners rather than a broad-based hike.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=229','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280095865&chamber=House&serialnumber=474']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='taxes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
