INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6793f0eb-ddaa-4c72-ac99-70876295279a', ct.id, $ctx$Voted Yea on the motion to kill LD 1134 (6/13/2025, RC #481), which would have barred transgender girls/women from female sports and facilities based on biological sex -- a Yea-on-Ought-Not-to-Pass vote keeps no such restriction in place, matching the scale's no-restrictions chair.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=House&serialnumber=481']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
