INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT 'e7f224d2-659a-41fd-887c-e2c714956bf8', ct.id, $ctx$Doudera voted Yea on 6/13/2025 to accept the House minority report "Ought Not to Pass" on LD 868, which would have required students to participate in school athletics, restrooms and housing based on biological sex, and voted Nay against the alternative report that would have advanced it as amended -- effectively voting to kill the restrictive bill and preserve the existing policy of participation matching gender identity without added restrictions.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=868','https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097110&chamber=H&serialnumber=490']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
