INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) SELECT '6a008bbb-a2dd-4128-87cf-f2fe0278738b', ct.id, $ctx$Voted Nay on the June 13, 2025 motion to accept the Ought Not To Pass report on LD 1134 ("An Act to Prohibit Males from Participating in Female Sports or Using Female Facilities") -- a Nay-on-ONTP vote that kept the bio-sex sports-restriction bill alive, indicating support for requiring athletes to compete based on biological sex.$ctx$, ARRAY['https://legislature.maine.gov/LawMakerWeb/rollcall.asp?ID=280097524&chamber=House&serialnumber=481','https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1134']::text[] FROM inform.compass_topics ct WHERE ct.topic_key='trans-athletes' ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
